// Kalender (ALLY 29, BA5, Stefan 20.10.2026): Termine der Person (Google Kalender über ALLY 13 wie in ALLY 8), Filter ab/Zeitraum/Suche, Tabelle sortierbar,
// Termin im Seitenfenster ändern oder löschen, neuer Termin im Dialog. Aktionen und Felder wie ALLY 8: termin_neu, termin_aendern, termin_loeschen.
// Daten: "Daten laden" (arbeit_web_seite 'kalender'), Termine aus "Arbeitsdaten laden (ALLY 13)", wenn ein Kalender hinterlegt ist. Liefert nur JSON.
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const X = $('Arbeitsdaten laden (ALLY 13)').isExecuted ? ($('Arbeitsdaten laden (ALLY 13)').first().json || {}) : {};
const F = E.funktion || {};
const P = E.parameter || {};
const titel = String(F.name || 'Kalender');
const kopf = { schluessel: 'kalender', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
const einst = { seite: 'einstellungen', parameter: { bereich: /^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || '')) ? String(F.einstellungen_ziel) : 'kalender' } };
kopf.zahnrad = { ziel: einst };
const W = D.w;
if (D.ok !== true || !W) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Der Kalender konnte nicht geladen werden. Bitte neu laden.' }] } } }];
if (!W.kalender_id) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Für dich ist noch kein Kalender hinterlegt.' },
  { typ: 'aktion', text: 'Kalender hinterlegen', ziel: einst }] } } }];
const K = X.kalender || null;
const termine = K && K.ok === true && Array.isArray(K.termine) ? K.termine : [];
const tag = t => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(t.tag || '')); if (!m) return String(t.tag || '');
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); return ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'][d.getUTCDay()] + ', ' + m[3] + '.' + m[2] + '.' + m[1]; };
const zeitText = t => t.ganz ? 'ganztägig' : String(t.von || '') + '–' + String(t.bis || '');
const heute = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin' }).format(new Date());
const jetzt = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
const filterWerte = Object.assign({}, P.von ? { von: P.von } : {}, P.tage ? { tage: P.tage } : {}, P.q ? { q: P.q } : {});
const hier = (extra, anker) => ({ seite: 'kalender', parameter: Object.assign({}, filterWerte, extra || {}), anker });
const ZR = { '1': '1 Tag', '7': '1 Woche', '14': '2 Wochen', '31': '1 Monat', '62': '2 Monate' };
const heuteListe = termine.filter(t => t.tag === heute && (t.ganz || String(t.bis || '') >= jetzt));
const woche = termine.filter(t => String(t.tag || '') >= heute && String(t.tag || '') <= new Date(Date.now() + 6 * 864e5).toISOString().slice(0, 10)).length;
const ueberblick = { kennzahlen: [
  { label: 'Termine', wert: K && K.ok === true ? String(termine.length) : '–', neben: ZR[String(W.tage)] || '' },
  { label: 'Heute', wert: String(termine.filter(t => t.tag === heute).length), neben: heuteListe.length ? heuteListe.length + ' noch offen' : '' },
  { label: 'Nächste 7 Tage', wert: String(woche), neben: '' },
  { label: 'Ganztägig', wert: String(termine.filter(t => t.ganz).length), neben: '' }],
  karten: [
    { titel: 'Offen', leer: 'Heute keine Termine mehr.', eintraege: heuteListe.slice(0, 5).map(t => ({ fett: zeitText(t), text: String(t.titel || '(ohne Titel)'), neben: String(t.ort || ''),
      ziel: hier({ termin: t.id }, 'a-termine'), ziel_text: 'Öffnen' })) },
    { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: K === null ? [{ marke: { text: 'Fehler', ton: 'warn' }, text: 'Die Termine konnten nicht geladen werden.' }]
      : K.ok !== true ? [{ marke: { text: 'Fehler', ton: 'warn' }, text: 'Der Kalender antwortet nicht: ' + String(K.fehler || '').slice(0, 200) }] : [] }] };
// Tabelle: sortierbar (Termin, Tag, Ort), 10 je Seite wie die Anzeige (Layout 11, Plan 38, Koordinator 24.10.2026, E8/E10: „Alle markieren“ = sichtbare Seite)
const JE = 10;
const ZU = D.zustand || {};
const SP = ['titel', 'tag', 'ort'];
const s0 = (ZU['kalender.termine'] || {}).sortierung || {};
const so = { spalte: SP.includes(s0.spalte) ? s0.spalte : 'tag', richtung: s0.richtung === 'auf' || s0.richtung === 'ab' ? s0.richtung : 'auf' };
const wert = (t, sp) => sp === 'tag' ? String(t.tag || '') + (t.ganz ? '00:00' : String(t.von || '')) : String(t[sp] || '').toLowerCase();
const sortiert = termine.map((t, i) => [t, i]).sort((a, b) => { const c = wert(a[0], so.spalte).localeCompare(wert(b[0], so.spalte), 'de', { numeric: true }); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
const seiten = Math.max(1, Math.ceil(sortiert.length / JE)), bl = Math.min(seiten, Math.max(1, Number((E.seiten || {}).termine) || 1));
const gew = String(P.termin || '');
const terminFelder = t => [
  { typ: 'text', name: 'titel', label: 'Titel', pflicht: true, wert: t ? String(t.titel || '') : '', breite: 'voll' },
  { typ: 'haken', name: 'ganztaegig', label: 'ganztägig', wert_an: '1', an: !!(t && t.ganz), breite: 'voll' },
  // Layout 11 (Prüfliste 6, Nachbesserung nach Prüfung pruefung_layout11): Beginn und Ende stehen immer da (die Datenbank verlangt sie; bei „ganztägig“ ohne Tage
  // nimmt ALLY 20 den Tag aus Beginn wie bisher), die Tage nur mit „ganztägig“; beim Ändern sind die Tage mit den Tagen von Beginn und Ende vorbelegt
  { typ: 'datum_zeit', name: 'start', label: 'Beginn', wert: t && !t.ganz ? String(t.start || '') : '' },
  { typ: 'datum_zeit', name: 'ende', label: 'Ende', wert: t && !t.ganz ? String(t.ende || '') : '' },
  { typ: 'datum', name: 'start_tag', label: 'Erster Tag (ganztägig)', wert: t ? String(t.tag || '') : '', zeigen_wenn: { feld: 'ganztaegig', werte: ['1'] } },
  { typ: 'datum', name: 'ende_tag', label: 'Letzter Tag (ganztägig)', wert: t ? (t.ganz ? String(t.ende_tag || '') : (/^\d{4}-\d{2}-\d{2}/.test(String(t.ende || '')) ? String(t.ende).slice(0, 10) : String(t.tag || ''))) : '',
    zeigen_wenn: { feld: 'ganztaegig', werte: ['1'] } },
  { typ: 'text', name: 'ort', label: 'Ort', wert: t ? String(t.ort || '') : '', breite: 'voll' }]
  .concat(t && t.notiz_fest ? [{ typ: 'versteckt', name: 'beschreibung_behalten', wert: '1' }, { typ: 'anzeige', name: 'notiz_anzeige', label: 'Notiz', wert: 'bleibt unverändert (Formatierung aus dem Kalender)', breite: 'voll' }]
    : [{ typ: 'textbereich', name: 'beschreibung', label: 'Notiz', wert: t ? String(t.beschreibung || '') : '', zeilen: 3, breite: 'voll' }]);
const abschnitte = [{ id: 'termine', titel: 'Termine', zahl: String(termine.length), offen_standard: true, inhalt: [
  { typ: 'filter', id: 'termine', label: 'Termine filtern', felder: [
    { typ: 'datum', name: 'von', label: 'Ab', wert: String(W.von || heute) },
    { typ: 'auswahl', name: 'tage', label: 'Zeitraum', wert: String(W.tage || '14'), optionen: Object.keys(ZR).map(k => ({ wert: k, text: ZR[k] })) },
    { typ: 'suche', name: 'q', label: 'Suchbegriff', wert: String(W.q || '') }] },
  { typ: 'tabelle', id: 'termine', titel: 'Termine', spalten: [{ schluessel: 'titel', titel: 'Termin', sortierbar: true }, { schluessel: 'tag', titel: 'Tag', sortierbar: true },
    { schluessel: 'zeit', titel: 'Zeit' }, { schluessel: 'ort', titel: 'Ort', sortierbar: true }],
    zeilen: sortiert.slice((bl - 1) * JE, bl * JE).map(t => ({ aktiv: gew === String(t.id), zellen: { titel: { text: String(t.titel || '(ohne Titel)'), ziel: hier({ termin: t.id }, 'a-termine') },
      tag: tag(t), zeit: zeitText(t), ort: String(t.ort || '') || '–' } })),
    sortierung: so, seite: bl, je_seite: JE, gesamt: sortiert.length, leer: K && K.ok === true ? 'Keine Termine in diesem Zeitraum.' : 'Die Termine konnten nicht geladen werden.' }] }];
const fenster = [{ id: 'neu', art: 'dialog', titel: 'Neuer Termin', inhalt: [{ typ: 'formular', id: 'termin-neu', aktion: 'termin_neu', spalten: 2, frage: 'Termin anlegen?',
  felder: terminFelder(null), knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Termin anlegen' }] }] }];
const sel = gew ? termine.find(t => String(t.id) === gew) : null;
if (sel) fenster.push({ id: 'termin', art: 'seitenfenster', offen: true, titel: String(sel.titel || '(ohne Titel)'), untertitel: tag(sel) + ' · ' + zeitText(sel),
  schliessen_ziel: hier({}, 'a-termine'), inhalt: [
    { typ: 'paare', eintraege: [{ label: 'Tag', wert: tag(sel) }, { label: 'Zeit', wert: zeitText(sel) }].concat(sel.ort ? [{ label: 'Ort', wert: String(sel.ort) }] : []) }]
    .concat(sel.notiz ? [{ typ: 'text', text: String(sel.notiz) }] : [], [
      { typ: 'unterueberschrift', text: 'Termin ändern' },
      { typ: 'formular', id: 'termin-aendern', aktion: 'termin_aendern', werte: { termin: sel.id }, spalten: 2, frage: 'Termin ändern? Teilnehmende werden nicht benachrichtigt.',
        felder: terminFelder(sel), knoepfe: [{ text: 'Änderung speichern' }] },
      { typ: 'aktion', text: 'Termin löschen', aktion: 'termin_loeschen', werte: { termin: sel.id }, frage: 'Termin „' + String(sel.titel || '') + '“ löschen? Der Termin wird im verbundenen Kalender gelöscht.' }]) });
kopf.hauptaktion = { text: 'Neuer Termin', fenster: 'neu' };
return [{ json: { inhalt: { seite: kopf, ueberblick: knapp(ueberblick), abschnitte, fenster } } }];

// Parameter (ALLY 29, Kalender): Sitzung; Filter ab (JJJJ-MM-TT), Zeitraum in Tagen (1, 7, 14, 31, 62), Suchbegriff (bis 100 Zeichen), gewählter Termin.
const E = $input.first().json;
const P = E.parameter || {};
const von = /^20[0-9]{2}-[01][0-9]-[0-3][0-9]$/.test(String(P.von || '')) ? String(P.von) : '';
const tage = ['1', '7', '14', '31', '62'].includes(String(P.tage || '')) ? String(P.tage) : '14';
const q = String(P.q || '').replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 100);
const termin = /^[A-Za-z0-9_-]{1,200}$/.test(String(P.termin || '')) ? String(P.termin) : '';
const d = Object.assign({ tage }, von ? { von } : {}, q ? { q } : {}, termin ? { termin } : {});
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify(d)] } }];
